          "answerText": "На с. 44 лишайники наведено як симбіоз із водоростями серед еукаріотичних груп; §3 вимагає, щоб класифікація відображала спорідненість і походження. Тому слово «лишайник» описує симбіотичну асоціацію партнерів, а не окремий монофілетичний таксон. Це обґрунтований висновок із цих двох фрагментів підручника.",
