          "correctKey": "Б",
          "answerText": "За прикладом §27 гетерозиготна рослина Bb при схрещуванні з рецесивною гомозиготою bb утворює нащадків Bb та bb порівну. Отже, половина має пурпурні, а половина — білі пелюстки. Тест перевіряє результат схеми; повна схема з обома можливими генотипами наведена у `ДЖЕРЕЛО 27.05`.",
